def seqs():
    outs=[]
    for k in range(n):
        outs.append(('row%d'%k, inp[k]))
        outs.append(('col%d'%k, [inp[r][k] for r in range(n)]))
        outs.append(('row%d_rev'%k, inp[k][::-1]))
        outs.append(('col%d_rev'%k, [inp[r][k] for r in range(n)][::-1]))
    return outs
