from itertools import permutations
n=4; n2=8
r=[rot(t,k) for k in range(4)]
def mk(p): return [r[p[0]][i]+r[p[1]][i] for i in range(4)]+[r[p[2]][i]+r[p[3]][i] for i in range(4)]
def arr(o):
    qs={'TL':[row[:4] for row in o[:4]],'TR':[row[4:] for row in o[:4]],
        'BL':[row[:4] for row in o[4:]],'BR':[row[4:] for row in o[4:]]}
    return tuple(next(k for k in range(4) if rot(t,k)==v) for v in qs.values())
P=mk((0,1,3,2))
# dihedral images of P
imgs={k:flips(P)[k] for k in flips(P)}
for k,v in imgs.items():
    try: print('P:',k,'->',arr(v))
    except StopIteration: print('P:',k,'-> not a pure rotation arrangement')
tried={(0,1,3,2),(0,3,1,2),(0,1,2,3),(3,0,2,1)}
print('untried symmetric:',[p for p in permutations(range(4)) if p not in tried and mk(p) and all(mk(p)==f for f in [mk(p)]) and True])
